-- Getting there, stage 2 (I2): the last 100 metres. Additive and idempotent.
--
-- 1. A new map layer, 'arrival' ("Parking & transport"), in `facilities`:
--    accessible parking, drop-off points (taxi ranks), accessible stops and
--    wharves near each venue — listings from OpenStreetMap (ODbL 1.0,
--    © OpenStreetMap contributors), always shown as unconfirmed, never a verdict.
--    A CHECK can't be widened in place, so the layer check is swapped for a
--    wider one in this same transaction (the one named exemption in
--    scripts/lib/migration-rules.ts; see AGENTS.md → Migrations). Every
--    existing row ('toilets', 'beach') passes the new check.
ALTER TABLE facilities DROP CONSTRAINT IF EXISTS facilities_layer_chk;
ALTER TABLE facilities ADD CONSTRAINT facilities_layer_chk CHECK (layer IN ('toilets', 'beach', 'arrival'));

-- 2. Step-by-step arrival from the community: "From The Corso turn into the
--    laneway; ramp on the left". One row = one ordered set of steps by one
--    person, with an optional photo (a review_photos row uploaded through the
--    existing photo upload). Others say "This worked for me"; the venue shows
--    the most-confirmed set. Describes how to get there; NEVER changes a verdict.
--    Shown by lived experience (`needs` snapshot, like reviews), never by name.
--    Rows go with the account (cascade); confirmed_by is cleaned on deletion.
CREATE TABLE IF NOT EXISTS arrival_steps (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  venue_id          text NOT NULL REFERENCES venues(id) ON DELETE CASCADE,
  user_id           text NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
  needs             text[] NOT NULL DEFAULT '{}'::text[],
  source            text NOT NULL DEFAULT 'community',
  from_place        text,
  steps             jsonb NOT NULL,                     -- ["Turn into the laneway", "Ramp on the left"]
  photo_id          uuid REFERENCES review_photos(id) ON DELETE SET NULL,
  confirmations     integer NOT NULL DEFAULT 0,
  confirmed_by      text[] NOT NULL DEFAULT '{}'::text[],
  last_confirmed_at timestamp with time zone NOT NULL DEFAULT now(),
  hidden            boolean NOT NULL DEFAULT false,
  created_at        timestamp with time zone NOT NULL DEFAULT now(),
  updated_at        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT arrival_steps_source_chk CHECK (source IN ('community', 'venue')),
  CONSTRAINT arrival_steps_steps_chk CHECK (jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) BETWEEN 1 AND 6)
);
CREATE INDEX IF NOT EXISTS arrival_steps_venue_idx ON arrival_steps USING btree (venue_id);
CREATE INDEX IF NOT EXISTS arrival_steps_photo_idx ON arrival_steps USING btree (photo_id);

